"""Bearer authentication for the CNA API (SEC-001 / ARCH-002; change set H).

The API is an internal service the web tier calls; historically it carried no
authentication and relied entirely on being network-private. The AWS appliance
violated that assumption by fronting it with an internet-facing ALB, so a bearer
is required on every request.

Two bearers are accepted, each only when configured:

* the shared secret ``CNA_API_TOKEN`` — generated by the appliance Terraform,
  stored in the cloud vault and injected into *both* the api and the web
  containers; compared with :func:`hmac.compare_digest`, never logged;
* an Entra ID access token for ``CNA_ENTRA_AUDIENCE`` (``entra.py``) — validated
  here for signature, issuer, audience and expiry; the internal router then
  requires its app role through :func:`entra.require_bearer`.

Liveness/readiness probes (``/health``, ``/ready``) are exempt so an
orchestrator can probe the container without holding either.
"""

from __future__ import annotations

import hmac
import logging
from collections.abc import Iterable

from entra import EntraValidator, claims_from_header
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import JSONResponse, Response
from starlette.types import ASGIApp

logger = logging.getLogger("cna-api")

# Probe endpoints an orchestrator must reach without the shared secret.
EXEMPT_PATHS: frozenset[str] = frozenset({"/health", "/ready"})


class BearerTokenMiddleware(BaseHTTPMiddleware):
    """Require ``Authorization: Bearer <token>`` on every non-exempt request.

    The shared-token comparison uses :func:`hmac.compare_digest` so a wrong
    token cannot be inferred from response timing, and the token itself is never
    logged. With an Entra validator a valid Entra token is accepted too and its
    claims are left on ``request.state.entra_claims`` for the internal router.
    At least one of the two must be configured.
    """

    def __init__(
        self,
        app: ASGIApp,
        *,
        token: str = "",
        entra: EntraValidator | None = None,
        exempt: Iterable[str] = EXEMPT_PATHS,
    ) -> None:
        super().__init__(app)
        if not token and entra is None:
            raise ValueError("BearerTokenMiddleware needs a shared token or an Entra validator")
        # Compare as bytes: ``hmac.compare_digest`` on ``str`` raises TypeError
        # for non-ASCII input, which an unauthenticated caller could use to
        # force 500s. Starlette decodes header values as latin-1, so encoding
        # the presented value back with latin-1 can never fail.
        self._token = token.encode("utf-8") if token else None
        self._entra = entra
        self._exempt = frozenset(exempt)

    async def dispatch(self, request: Request, call_next) -> Response:  # noqa: ANN001
        if request.url.path in self._exempt:
            return await call_next(request)

        header = request.headers.get("Authorization", "")
        scheme, _, presented = header.partition(" ")
        # A missing header yields an empty presented value, which never
        # matches a real token; any non-ASCII byte sequence is simply unequal.
        if scheme.lower() == "bearer" and self._token is not None:
            if hmac.compare_digest(presented.encode("latin-1"), self._token):
                return await call_next(request)
        if self._entra is not None:
            claims = claims_from_header(self._entra, header)
            if claims is not None:
                request.state.entra_claims = claims
                return await call_next(request)
        return JSONResponse(
            {"detail": "unauthorized"}, status_code=401, headers={"WWW-Authenticate": "Bearer"}
        )
